 47	    public Xtw92 createOrderBid(String email, Long productSizeId, int bidPrice) {
 48	        try {
 49	
 50	            validateCreateOrderBidInput(email, productSizeId, bidPrice);
 51	
 52	
 53	            Xjm45 user = userQueryService.findByEmail(email);
 54	
